initData();
function route(){const p=new URLSearchParams(location.hash.replace(/^#/,''));return {view:p.get('view')||'moderation',tab:p.get('tab')||(p.get('view')==='site'?'profiles':'reviews'),detail:p.get('detail')||'',scope:p.get('scope')||'all',status:p.get('status')||'pending',q:p.get('q')||'',page:Math.max(1,Math.floor(Number(p.get('page'))||1)),version:p.get('version')||'submitted',enabled:p.get('enabled')||'all'};}
const pBy=id=>profiles.find(x=>x.id===id);
const personName=(p,content=false)=>content?C(p.name,p.en):T(p.name,p.en);
const recordBy=(id)=>reviews.concat(replies).find(r=>r.id===id);
const currentRecord=()=>recordBy(route().detail);
const profileName=(id)=>personName(pBy(id));
function avatar(p,size=''){return `<span class="avatar ${p.color} ${size}" aria-hidden="true">${esc(state.lang==='en'?p.en[0]:p.name[0])}</span>`;}
function go(patch,opts={}){
 const r=route();const next={...r,...patch};
 if(opts.remember){state.scrolls[`${r.view}/${r.tab}`]=window.scrollY;}
 if(opts.restore)state.restoreY=state.scrolls[`${next.view}/${next.tab}`]||0;
 if(opts.preserve)state.preserveY=window.scrollY;
 if(!opts.skipGuard&&r.detail&&next.detail!==r.detail&&state.notes[r.detail]?.trim()){
  showModal('leave',()=>go(patch,{...opts,skipGuard:true}));return;
 }
 if(r.view==='site'&&r.tab==='accounts'&&(next.view!=='site'||next.tab!=='accounts')){cancelDemoAccount();state.formPassword='';}
 const p=new URLSearchParams();for(const [k,v]of Object.entries(next)){if(v!==''&&v!==undefined)p.set(k,String(v));}
 if(location.hash.slice(1)===p.toString()){render();return;}location.hash=p.toString();
}
function shell(content){const r=route();const nav=(v,label,ic,tab='')=>`<a href="#view=${v}${tab?'&tab='+tab:''}" data-nav="${v}:${tab}" class="${r.view===v?'active':''}" ${r.view===v?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></a>`;
 return `<div class="ws-utility"><strong>${T('Plotstay · 私人工作台','Plotstay · Private workspace')}</strong><span class="utility-sub">${T('创作与管理','Create and manage')}</span><nav aria-label="${T('界面语言','Interface language')}"><button data-action="ui-zh" class="${state.lang==='zh'?'active':''}">中文</button><button data-action="ui-en" class="${state.lang==='en'?'active':''}">English</button></nav></div><div class="ws-shell"><aside class="ws-sidebar ${state.menu?'open':''}"><a class="ws-brand" href="#" data-action="outside"><span class="ws-brand-icon">P</span><span>PLOTSTAY</span></a><button class="menu-btn" data-action="menu" aria-expanded="${state.menu}">${icon('menu')}${T('导航','Menu')}</button><p class="ws-nav-label">${T('我的工作台','My workspace')}</p><nav class="ws-nav" aria-label="${T('工作台导航','Workspace navigation')}">${nav('overview',T('概览','Overview'),'home')}${nav('personas',T('我的角色','My personas'),'person')}${nav('my-reviews',T('我的评价','My reviews'),'review')}${nav('received',T('收到的评价','Received reviews'),'reply')}<p class="ws-nav-group">${T('我的内容','My content')}</p>${nav('works',T('我管理的内容','Content I manage'),'building')}${nav('worlds',T('我管理的世界','Worlds I manage'),'world')}${nav('settings',T('账号设置','Account settings'),'settings')}<p class="ws-nav-group">${T('审核管理','Moderation')}</p>${nav('moderation',T('评价与回复审核','Review moderation'),'shield','reviews')}${state.role==='site'?nav('site',T('网站管理','Site management'),'site','profiles'):''}</nav><div class="ws-sidebar-footer"><div class="ws-account-mark">X</div><div><strong>xingwu</strong><small>${state.role==='site'?T('网站管理员','Site administrator'):T('世界管理员','World administrator')}</small></div><a class="ws-legacy" href="#" data-action="outside">${T('旧版 ↗','Previous ↗')}</a></div></aside><main class="ws-main" id="main" tabindex="-1">${content}</main></div>`;
}
function navigation(backLabel,action,current){return `<div class="ws-page-navigation"><a class="back" href="#" data-action="${action}">${icon('back')}${backLabel}</a><nav class="crumbs" aria-label="${T('面包屑','Breadcrumb')}"><a href="#" data-action="outside">${T('我的工作台','My workspace')}</a><span class="separator">/</span><span>${current}</span></nav></div>`;}
function heading(title,desc,right='',eyebrow=''){return `<header class="page-head"><div><p class="eyebrow">${eyebrow||T('审核管理','MODERATION')}</p><h1>${title}</h1><p class="page-context">${desc}</p></div>${right}</header>`;}
function scopeControl(){const r=route();return `<div class="scope-select"><label for="scope">${T('审核范围','Review scope')}</label><select id="scope" data-select="scope" aria-label="${T('审核范围','Review scope')}"><option value="all" ${r.scope==='all'?'selected':''}>${state.role==='site'?T('全站 · 全部世界','Site-wide · All worlds'):T('全部可审核的世界','All authorised worlds')}</option><option value="lathe" ${r.scope==='lathe'?'selected':''}>${worldName('lathe')}</option><option value="mist" ${r.scope==='mist'?'selected':''}>${worldName('mist')}</option></select></div>`;}
function pendingCount(type){const r=route();if(state.scenario==='empty')return 0;if(state.scenario==='error')return '—';const list=type==='reviews'?reviews:replies;return list.filter(x=>x.submission==='pending'&&(r.scope==='all'||x.world===r.scope)).length;}
function moderationTabs(){const r=route();return `<nav class="tabs" aria-label="${T('审核对象','Review type')}">${['reviews','replies'].map(tab=>`<button data-action="mod-tab" data-value="${tab}" class="${r.tab===tab?'active':''}" ${r.tab===tab?'aria-current="page"':''}>${tab==='reviews'?T('评价审核','Reviews'):T('提供者回复审核','Provider replies')}<span class="count" aria-label="${T('待审核数量','Pending count')}">${pendingCount(tab)}</span></button>`).join('')}</nav>`;}
function siteTabs(){const r=route();return `<nav class="tabs" aria-label="${T('网站管理栏目','Site management sections')}">${[['profiles',T('角色资料审核','Persona profiles')],['accounts',T('创建普通账号','Create account')],['bindings',T('条目提供者绑定','Provider assignment')]].map(([tab,title])=>`<button data-action="site-tab" data-value="${tab}" class="${r.tab===tab?'active':''}" ${r.tab===tab?'aria-current="page"':''}>${title}${tab==='profiles'?`<span class="count">${state.scenario==='error'?'—':state.scenario==='empty'?0:profiles.filter(p=>p.status==='pending').length}</span>`:''}</button>`).join('')}</nav>`;}
function statusOptions(profile=false){const r=route();const list=profile?[['pending',T('待审核','Pending')],['approved',T('已批准','Approved')],['rejected',T('已退回','Returned')],['all',T('全部','All')]]:[['pending',T('待审核','Pending')],['rejected',T('已退回','Returned')],['published',T('公开中','Public')],['hidden',T('已隐藏','Hidden')],['all',T('全部','All')]];return list.map(([v,t])=>`<option value="${v}" ${r.status===v?'selected':''}>${t}</option>`).join('');}
function filterBar(profile=false){const r=route();return `<form class="filters ${profile?'profile-filters':''}" id="queue-search"><label class="field filter-state"><span>${T('审核状态','Review status')}</span><select data-select="status" aria-label="${T('审核状态','Review status')}">${statusOptions(profile)}</select></label>${profile?`<label class="field filter-state"><span>${T('角色状态','Persona status')}</span><select data-select="enabled" aria-label="${T('角色状态','Persona status')}"><option value="all" ${r.enabled==='all'?'selected':''}>${T('全部状态','All')}</option><option value="yes" ${r.enabled==='yes'?'selected':''}>${T('启用中','Enabled')}</option><option value="no" ${r.enabled==='no'?'selected':''}>${T('已停用','Disabled')}</option></select></label>`:''}<label class="field search-field"><span>${T('搜索','Search')}</span><div class="search-input">${icon('search')}<input name="q" value="${esc(r.q)}" placeholder="${profile?T('角色名称或所属账号','Persona name or owner'):T('条目、署名角色、作者或正文','Entry, persona, author or text')}" autocomplete="off" aria-label="${T('搜索关键词','Search terms')}"></div></label><div class="buttons"><button class="btn" type="submit">${T('搜索','Search')}</button>${btn(T('重置','Reset'),'reset-filters','text')}</div></form>`;}
function emptyState(error=false){return `<section class="empty-state"><div class="empty-icon">${icon(error?'warn':'inbox')}</div><h2>${error?T('暂时无法载入审核列表','Could not load the queue'):T('没有需要处理的事项','Nothing awaiting review')}</h2><p>${error?T('这不是空列表。筛选条件已保留，请重试。','This is not an empty queue. Your filters are preserved. Please retry.'):T('当前范围内没有符合筛选条件的事项。','There are no matching items in the current scope.')}</p>${btn(error?T('重新载入','Try again'):T('清除筛选','Clear filters'),error?'retry':'reset-filters','')}</section>`;}
function stateFor(r){const p=pBy(r.profile);if(r.submission==='pending'){if(p.status==='pending')return [T('等待资料审核','Profile review needed'),'waiting'];if(p.disabled)return [T('角色已停用','Persona disabled'),'waiting'];return [r.hasHistory?T('新版本待审','Update pending'):T('待审核','Pending'),'pending'];}if(r.submission==='rejected')return [T('已退回','Returned'),'returned'];return r.published?[T('已公开','Public'),'live']:[T('已隐藏','Hidden'),'hidden'];}
function publicSub(r){return r.published?T('当前公开版仍在展示','Current version remains public'):r.hidden?T('公开内容已隐藏','Publication hidden'):T('尚未公开','Not yet public');}
function row(r){const p=pBy(r.profile);const [status,kind]=stateFor(r);return `<article class="queue-row" data-record="${r.id}"><div class="col-copy"><h3><a href="#" data-action="open-record" data-id="${r.id}">${esc(T(r.title,r.titleEn))}</a></h3><div class="row-context"><span class="world-label">${worldName(r.world)}</span><span>${kindName(r.kind)} · ${esc(T(r.entry,r.entryEn))}</span></div><p class="snippet">${esc(T(r.body[0],r.bodyEn[0]))}</p></div><div class="col-identity"><div class="identity">${avatar(p)}<div><div class="identity-name">${esc(personName(p))}</div><div class="identity-sub">${T('作者','Author')} · ${esc(p.owner)}</div></div></div></div><div class="col-state">${tag(status,kind)}<p class="state-sub">${publicSub(r)}</p><span class="mobile-time">${r.day} ${r.time}</span></div><div class="col-time time">${r.day}<span>${r.time}</span></div><div class="col-action row-action">${btn(r.submission==='pending'?T('查看并审核','Review'):T('查看详情','View details'),'open-record','',`data-id="${r.id}"`)}</div></article>`;}
function pagination(count,page,pages){return `<nav class="pagination" aria-label="${T('分页','Pagination')}"><span class="total">${T(`共 ${count} 项 · 每页 5 项`,` ${count} items · 5 per page`)}</span>${btn(T('上一页','Previous'),'page','',`data-value="${page-1}" ${page<=1?'disabled':''}`)}<span class="pagenum">${page}</span><span>/ ${pages}</span>${btn(T('下一页','Next'),'page','',`data-value="${page+1}" ${page>=pages?'disabled':''}`)}</nav>`;}
function moderationList(){const r=route();let list=(r.tab==='replies'?replies:reviews).filter(x=>r.scope==='all'||x.world===r.scope);list=list.filter(x=>r.status==='all'||r.status==='pending'&&x.submission==='pending'||r.status==='rejected'&&x.submission==='rejected'||r.status==='published'&&x.published||r.status==='hidden'&&x.hidden);if(r.q.trim()){const q=r.q.toLowerCase().trim();list=list.filter(x=>JSON.stringify([x.title,x.titleEn,x.entry,x.entryEn,x.body,x.bodyEn,profileName(x.profile),pBy(x.profile).owner]).toLowerCase().includes(q))};let body='';const needed=list.filter(x=>x.submission==='pending'&&pBy(x.profile).status==='pending').length;const pages=Math.max(1,Math.ceil(list.length/5)),page=Math.min(r.page,pages);if(state.scenario==='error'||state.scenario==='empty')body=emptyState(state.scenario==='error');else if(!list.length)body=emptyState();else body=`<div class="queue-caption"><span><strong>${T(`找到 ${list.length} 项`,` ${list.length} matching items`)}</strong>${needed?` · ${T(`其中 ${needed} 项需先审核署名资料`,`${needed} also need profile review`)}`:''}</span><span>${T('最近送审优先','Most recently submitted first')}</span></div><section class="queue-panel"><div class="queue-head"><span>${r.tab==='replies'?T('回复与所属条目','Reply and entry'):T('评价与所属条目','Review and entry')}</span><span>${T('署名角色 / 实际作者','Persona / author')}</span><span>${T('审核 / 公开状态','Review / publication')}</span><span class="col-time">${T('送审时间','Submitted')}</span><span></span></div>${list.slice((page-1)*5,page*5).map(row).join('')}</section>${pagination(list.length,page,pages)}<p class="footnote">${T('页签数字为当前世界范围的待审核总数，包含等待角色资料审核的发言。','Tab counts include all pending submissions in the selected scope, including those awaiting profile review.')}</p>`;
return navigation(T('返回工作台','Back to workspace'),'outside',T('评价与回复审核','Review moderation'))+heading(T('评价与回复审核','Review moderation'),T('审核评价和提供者回复；查看原文、署名与固定送审版本。','Review feedback and provider replies in the worlds you can moderate.'),scopeControl())+moderationTabs()+filterBar()+body;}
function profileRow(p){return `<article class="queue-row"><div class="col-copy"><div class="identity">${avatar(p)}<div><div class="identity-name"><a href="#" data-action="open-profile" data-id="${p.id}">${esc(personName(p))}</a></div><div class="identity-sub">${T('所属账号','Owner')} · ${esc(p.owner)}</div></div></div></div><div class="col-type subtype">${p.currentVersion?T('修改资料','Profile update'):T('首次送审','First submission')}<small>${T(`送审 v${p.version}`,`Submission v${p.version}`)}</small></div><div class="col-state">${tag(p.status==='pending'?T('待审核','Pending'):p.status==='approved'?T('已批准','Approved'):T('已退回','Returned'),p.status==='pending'?'pending':p.status==='approved'?'live':'returned')}</div><div class="col-enabled">${tag(p.disabled?T('已停用','Disabled'):T('启用中','Enabled'),p.disabled?'hidden':'subtle')}</div><div class="col-time time">${p.stamp}<span>${p.time}</span></div><div class="col-action row-action">${btn(p.status==='pending'?T('查看并审核','Review'):T('查看详情','View details'),'open-profile','',`data-id="${p.id}"`)}</div></article>`;}
function profileList(){const r=route();let list=profiles.filter(p=>(r.status==='all'||p.status===r.status)&&(r.enabled==='all'||(((r.enabled==='no')===p.disabled))));if(r.q.trim()){const q=r.q.toLowerCase();list=list.filter(p=>[p.name,p.en,p.owner,p.email].join(' ').toLowerCase().includes(q));}const pages=Math.max(1,Math.ceil(list.length/5)),page=Math.min(r.page,pages);return `<div class="site-info">${icon('info')}<p>${T('资料批准与角色启用是两回事。批准资料不会自动发布关联发言。','Profile approval and persona availability are separate. Approval does not publish associated posts.')}</p></div>${filterBar(true)}${state.scenario==='error'||state.scenario==='empty'?emptyState(state.scenario==='error'):!list.length?emptyState():`<div class="queue-caption"><strong>${T(`找到 ${list.length} 项资料申请`,`${list.length} profile submissions`)}</strong><span>${T('最近送审优先','Most recently submitted first')}</span></div><section class="queue-panel profile-grid"><div class="queue-head"><span>${T('角色 / 所属账号','Persona / owner')}</span><span>${T('本次申请','Submission')}</span><span>${T('资料审核','Profile review')}</span><span>${T('角色状态','Availability')}</span><span class="col-time">${T('送审时间','Submitted')}</span><span></span></div>${list.slice((page-1)*5,page*5).map(profileRow).join('')}</section>${pagination(list.length,page,pages)}`}`;}
function sitePage(){const r=route();if(state.role!=='site')return navigation(T('返回审核列表','Back to reviews'),'back-moderation',T('网站管理','Site management'))+heading(T('没有网站管理权限','Site administrator access required'),T('你的世界审核权限不会授予网站级操作权限。','World moderation does not grant site administration access.'));
return navigation(T('返回工作台','Back to workspace'),'outside',T('网站管理','Site management'))+heading(T('网站管理','Site management'),T('处理角色资料审核，使用账号与条目管理工具。','Review persona profiles and access account and provider tools.'),`<div class="scope-static">${icon('shield')}${T('全站范围 · 仅网站管理员','Site-wide · Administrator only')}</div>`)+siteTabs()+(r.tab==='accounts'?accountForm():r.tab==='bindings'?bindingForm():profileList());}
function recordContext(r){return `<div class="context-strip"><div class="context-icon">${icon('building')}</div><div class="context-copy"><h2>${esc(T(r.entry,r.entryEn))}<span class="tag subtle" style="margin-left:8px;font-size:10px">${kindName(r.kind)}</span></h2><p>${T('所属世界','World')} · ${worldName(r.world)} &nbsp; / &nbsp; ${T('发言所属条目','Entry associated with this post')}</p></div><a href="#" data-action="outside">${T('查看所属条目 ↗','View entry ↗')}</a></div>`;}
function languagePicker(){return `<div class="lang-picker" aria-label="${T('内容语言','Content language')}"><button type="button" data-action="content-zh" class="${state.contentLang==='zh'?'active':''}">中文</button><button type="button" data-action="content-en" class="${state.contentLang==='en'?'active':''}">English</button></div>`;}
function historyBlock(r){return `<details class="history"><summary>${icon('history')}<span class="history-title">${T('审核与公开记录','Review and publication history')}</span><span class="small">${T('展开记录','Show history')} ${icon('down')}</span></summary><div class="events"><div class="event"><strong>${T('本次版本送审','Current version submitted')}</strong><small>2026-${r.day} ${r.time} · ${esc(pBy(r.profile).owner)} · v${r.version}</small></div>${r.draft?`<div class="event"><strong>${T('作者保存了后续草稿','Author saved a later draft')}</strong><small>${T('未包含在本次审核中','Not included in this decision')} · v${r.version+1}</small></div>`:''}${r.hasHistory?`<div class="event"><strong>${T('旧版本已发布','Earlier version published')}</strong><small>2026-10-12 16:40 · xingwu · v${r.pubVersion}</small></div>`:''}${state.success[r.id]?`<div class="event"><strong>${esc(state.success[r.id])}</strong><small>${T('本次原型演示 · 不写入真实历史','Prototype demonstration · Not recorded in production')}</small></div>`:''}</div></details>`;}
function notice(kind,title,body,ic='info'){return `<section class="notice ${kind}">${icon(ic)}<div><h3>${title}</h3>${body}</div></section>`;}
function recordDetail(){const r=currentRecord();if(!r)return emptyState(true);const p=pBy(r.profile),rt=route(),isReply=r.type==='reply';const active=rt.version;
let content= navigation(T('返回审核列表','Back to moderation'),'back-moderation',isReply?T('评价与回复审核 / 回复详情','Moderation / Provider reply'):T('评价与回复审核 / 评价详情','Moderation / Review'))+heading(isReply?T('提供者回复审核','Review provider reply'):T('评价审核','Review submission'),`${T('实际作者','Author')} · ${esc(p.owner)} &nbsp; / &nbsp; ${T('送审','Submitted')} · 2026-${r.day} ${r.time}`,`<div class="scope-static">${icon('world')}${worldName(r.world)}</div>`,T('固定送审版本','FIXED SUBMISSION'))+recordContext(r);
if(isReply){const par=recordBy(r.parent);content+=`<details class="panel original-review"><summary><strong>${T('原评价','Original review')} · ${esc(T(par.title,par.titleEn))}</strong><span>${T('展开全文','Read in full')} ${icon('down')}</span></summary><p class="original-intro">${C(par.body.join('<br><br>'),par.bodyEn.join('<br><br>'))}</p></details>`;}
const reference=active!=='submitted';let copy=active==='public'?C(['我到的时候已经过了熄灯时间。值夜人把钥匙和一盏灯推到我面前。房间很安静，热水也准时送达。'],['I arrived after lights-out. The night attendant gave me a key and a lamp. The room was quiet, and hot water arrived on time.']):active==='draft'?C([...r.body,'补充：下次准备试试朝向内院的房间。'],[...r.bodyEn,'A later note: next time I will try a courtyard-facing room.']):C(r.body,r.bodyEn);
if(active==='public')copy=C(r.publicBody,r.publicBodyEn);
content+=`<section class="panel"><div class="versions" aria-label="${T('版本选择','Version selection')}">${[['submitted',T('本次送审版','Submitted'),r.version],...(r.hasHistory?[['public',r.published?T('当前公开版','Published'):T('上次公开版','Last publication'),r.pubVersion]]:[]),...(r.draft?[['draft',T('后续草稿','Later draft'),r.version+1]]:[])].map(([v,n,num])=>`<button data-action="version" data-value="${v}" class="${active===v?'active':''}">${n}<span class="version-id">v${num}</span></button>`).join('')}${languagePicker()}</div><div class="read-state ${reference?'reference':''}">${icon(reference?'info':'lock')}${reference?T('仅供参考，此版本不参与本次审核。请返回本次送审版作出决定。','Reference only. Return to the submitted version to make a decision.'):T(`固定送审 v${r.version} · 正文、译文和署名不会随作者后续修改而变化。`,`Fixed submission v${r.version} · Text, translations and signature are frozen.`)}</div><div class="reading-grid"><div class="reading-copy"><h2>${esc(C(r.title,r.titleEn))}</h2>${!isReply?`<div class="rating">★★★★☆ <span class="muted">4.0 / 5</span></div>`:''}${copy.map(x=>`<p>${esc(x)}</p>`).join('')}</div><aside class="signature"><div class="signature-label">${active==='public'?T('历史公开署名','PUBLISHED SIGNATURE'):active==='draft'?T('后续草稿署名','LATER DRAFT SIGNATURE'):T('本次送审署名','SUBMITTED SIGNATURE')}</div><div class="identity">${avatar(p)}<div><strong class="identity-name">${esc(personName(p,true))}</strong><div class="identity-sub">${T('资料版本','Profile version')} v${active==='public'?r.publicProfileVersion:p.version}</div></div></div>${active==='public'?tag(T('历史署名快照','Historical signature'),'subtle'):tag(p.status==='pending'?T('资料待审核','Profile pending'):p.status==='approved'?T('资料已批准','Profile approved'):T('资料已退回','Profile returned'),p.status==='pending'?'waiting':p.status==='approved'?'live':'returned')}<p>${esc(active==='public'?C(r.publicBio,r.publicBioEn):C(p.bio,p.bioEn))}</p><div class="signature-meta">${T('实际作者账号','Author account')}<br><strong>${esc(p.owner)}</strong>${state.role==='site'?`<br><a class="ref-link" href="#" data-action="open-profile" data-id="${p.id}">${T('单独审核角色资料 →','Review profile separately →')}</a>`:''}</div></aside></div></section>`;
if(r.draft&&active==='submitted')content+=`<p class="nonblocking-note">${T(`作者另有后续草稿 v${r.version+1}。本次只审核 v${r.version}，不会一并发布未送审修改。`,`A later draft v${r.version+1} exists. This decision applies to v${r.version} only.`)}</p>`;
const joint=p.status==='pending'&&state.role==='site'&&!p.disabled;
const blocked=p.disabled||(p.status!=='approved'&&!joint);
if(!reference&&r.submission==='pending'){
 if(p.disabled)content+=notice('error',T('不能发布：署名角色已停用','Cannot publish: persona is disabled'),`<p>${T('停用不会自动隐藏历史发言。当前送审版不能发布，请先核对角色状态。','Disabling a persona does not hide past posts. This submission cannot be published while the persona is disabled.')}</p>`,'lock');
 else if(joint)content+=notice('',T('本次批准包含一项网站级决定','This approval includes a site-wide decision'),`<p>${T('下方主按钮会同时执行两项操作，请核对影响范围。','The primary button performs both actions below. Check their scope before continuing.')}</p><div class="effect-grid"><div class="effect"><span class="effect-label">${T('网站级 · 不限当前世界','SITE-WIDE · NOT LIMITED TO THIS WORLD')}</span><h4>${T('批准角色资料','Approve persona profile')} · ${esc(personName(p))} v${p.version}</h4><p>${T('批准本条发言引用的固定资料版本。其他引用同一版本的发言可能解除资料审核阻塞。','Approve the exact profile version used here. Other posts using this version may no longer be blocked by profile review.')}</p></div><div class="effect"><span class="effect-label">${worldName(r.world)} · ${T('仅当前发言','THIS POST ONLY')}</span><h4>${isReply?T('发布此回复','Publish this reply'):T('发布此评价','Publish this review')} · v${r.version}</h4><p>${r.published?T('本次送审版将替换当前公开版。','The submitted version will replace the current public version.'):T('将本次送审版公开显示在所属条目下。','Make this submission visible under its entry.')}</p></div></div><p class="effect-foot"><strong>${T('不会自动发布其他评价或回复，也不会发布后续草稿。','Other reviews, replies and later drafts will not be published.')}</strong></p>`,'warn');
 else if(blocked)content+=notice('',T(p.status==='rejected'?'不能发布：署名资料已被退回':'暂时不能发布：署名资料尚未批准',p.status==='rejected'?'Cannot publish: profile was returned':'Cannot publish yet: profile approval needed'),`<p>${T('角色资料需要网站管理员审核。你仍可阅读或退回本次发言，但不能批准角色资料。','A site administrator must review the profile. You can still read or return this submission, but cannot approve the profile.')}</p>`,'lock');
 }
if(state.scenario==='conflict')content+=notice('error',T('此申请已被另一位管理员处理','Another administrator has handled this submission'),`<p>${T('你正在查看的决定已过期。审核说明仍保留，不会自动套用到其他版本。','This decision is stale. Your note is preserved and will not be applied to another version.')}</p>${btn(T('刷新最新状态','Refresh status'),'resolve-conflict','small')}`,'warn');
content+=historyBlock(r);
if(state.success[r.id])content+=notice('success',T('演示操作已完成','Demo action completed'),`<p>${esc(state.success[r.id])}</p>`,'check');
if(r.submission==='pending'){
content+=`<section class="panel decision-panel"><div class="decision-head"><h2>${T('审核决定','Review decision')}</h2>${tag(T(`仅对送审 v${r.version} 作出决定`,`Applies to submitted v${r.version}`),'subtle')}</div><div class="decision-body"><label class="field"><span>${T('审核说明（选填）','Review note (optional)')}</span><textarea id="review-note" data-note="${r.id}" placeholder="${T('说明通过或退回的原因，便于作者理解……','Explain the decision so the author knows what to change…')}">${esc(state.notes[r.id]||'')}</textarea></label><p class="decision-note">${T('这里只填写审核说明，不修改作者的正文。','This field records your decision note; it does not edit the author’s text.')}</p></div><div class="decision-actions"><p class="action-help">${r.published?T('退回只处理本次送审，当前公开版仍会展示。','Returning this submission keeps the current publication visible.'):T('退回不会删除内容，作者可修改后重新送审。','Returning a submission does not delete it.')}</p>${reference?btn(T('返回送审版审核','Return to submitted version'),'version','primary','data-value="submitted"'):btn(isReply?T('退回本次回复','Return reply'):T('退回本次送审','Return submission'),'return-record','',`${state.scenario==='conflict'?'disabled':''}`)+btn(joint?(isReply?T('批准角色资料并发布此回复','Approve profile and publish reply'):T('批准角色资料并发布此评价','Approve profile and publish review')):(isReply?T('通过并发布回复','Approve and publish reply'):T('通过并发布','Approve and publish')),'publish-record','primary',`${blocked||state.scenario==='conflict'?'disabled':''}`)}</div></section>`;
}else content+=`<div class="readback-result"><strong>${r.submission==='rejected'?T('本次送审已退回','This submission was returned'):T('当前没有待处理的送审版本','No pending submission')}</strong><p>${publicSub(r)}</p></div>`;
if(r.hasHistory)content+=`<section class="publication-area"><div><h3>${T('公开状态管理','Publication controls')} · ${r.published?T('当前公开中','Currently public'):T('已隐藏','Hidden')}</h3><p>${T('独立于上方审核决定，只处理公开内容。','These controls affect publication, separately from the submission decision.')}</p></div>${r.published?btn(T('隐藏公开内容','Hide publication'),'hide-record','danger'):''}${btn(T('恢复历史公开版本','Restore past publication'),'restore-record','')}</section>`;
return content;}
function profileVersion(p,submitted){const ver=submitted?p.version:p.currentVersion;const bio=submitted?C(p.bio,p.bioEn):C(p.oldBio||p.bio,p.oldBioEn||p.bioEn);return `<section class="profile-version ${submitted?'submitted':'current'}"><div class="profile-version-head"><strong>${submitted?T('本次送审资料','Submitted profile'):T('当前已批准资料','Current approved profile')}</strong><span>${ver?'v'+ver:T('尚无','None')}</span></div><div class="profile-version-body">${!ver?`<p class="muted small">${T('这是首次送审，尚无已批准资料。','This is the first submission; no approved profile exists.')}</p>`:`<div class="profile-field"><span>${T('头像与名称','Avatar and name')}</span><div class="identity">${avatar(p)}<strong>${esc(personName(p,true))}</strong></div></div><div class="profile-field"><span>${T('设定 / 简介','Bio / description')}${submitted&&p.currentVersion?` · ${T('有修改','Changed')}`:''}</span><p class="${submitted&&p.currentVersion?'changed':''}">${esc(bio)}</p></div>`}</div></section>`;}
function profileDetail(){const rt=route(),p=pBy(rt.detail);if(!p||state.role!=='site')return emptyState(true);const refs=reviews.concat(replies).filter(x=>x.profile===p.id&&x.submission==='pending');let content=navigation(T('返回角色资料列表','Back to profiles'),'back-profiles',T('网站管理 / 角色资料审核','Site management / Profile review'))+heading(T('角色资料审核','Review persona profile'),`${esc(personName(p))} · ${T('所属账号','Owner')} ${esc(p.owner)} &nbsp; / &nbsp; 2026-${p.stamp} ${p.time}`,`<div class="scope-static">${icon('shield')}${T('网站级资料审核','Site-wide profile review')}</div>`,T('固定送审资料','FIXED PROFILE SUBMISSION'));
if(state.fromRecord)content+=`<p class="nonblocking-note"><a href="#" class="ref-link" data-action="back-source">← ${T('返回刚才的发言审核','Return to the originating submission')}</a></p>`;
content+=`<section class="panel profile-compare"><div class="compare-top"><h2>${T('资料版本对照','Profile comparison')}</h2>${languagePicker()}</div><div class="compare-grid">${profileVersion(p,false)}${profileVersion(p,true)}</div><p class="profile-meta">${icon('lock')}${T(`本次决定针对固定送审 v${p.version}，不包含后续草稿或私人笔记。`,`This decision applies to submitted v${p.version}. Later drafts and private notes are excluded.`)}</p></section>`;
content+=notice('info',T('批准资料，不等于发布发言','Approving a profile does not publish posts'),`<p>${T('这里只批准这份角色资料。不会自动发布关联评价或回复，也不会改写历史发言的署名。','This approves the profile only. It does not publish associated posts or rewrite historical signatures.')}</p>`,'info');
if(refs.length)content+=`<details class="panel original-review"><summary><strong>${T(`引用此资料版本的待审发言 · ${refs.length} 项`,`Pending posts using this version · ${refs.length}`)}</strong><span>${T('查看关联','View related')} ${icon('down')}</span></summary>${refs.map(x=>`<div class="ws-list-row" style="padding:13px 0;border-top:1px solid var(--line);margin-top:10px"><a class="ref-link" href="#" data-action="open-record" data-id="${x.id}">${esc(T(x.title,x.titleEn))}</a><p class="small muted">${worldName(x.world)} · ${x.type==='reply'?T('提供者回复','Provider reply'):T('评价','Review')}</p></div>`).join('')}</details>`;
content+=`<details class="history"><summary>${icon('history')}<span class="history-title">${T('资料审核记录','Profile review history')}</span>${icon('down')}</summary><div class="events"><div class="event"><strong>${T('资料送审','Profile submitted')}</strong><small>2026-${p.stamp} ${p.time} · ${esc(p.owner)} · v${p.version}</small></div>${p.currentVersion?`<div class="event"><strong>${T('上次资料已批准','Previous profile approved')}</strong><small>2026-10-12 10:25 · xingwu · v${p.currentVersion}</small></div>`:''}</div></details>`;
if(state.success[p.id])content+=notice('success',T('演示操作已完成','Demo action completed'),`<p>${esc(state.success[p.id])}</p>`,'check');
if(p.status==='pending')content+=`<section class="panel decision-panel"><div class="decision-head"><h2>${T('资料审核决定','Profile decision')}</h2>${tag(T('不包含发言发布','Does not publish posts'),'subtle')}</div><div class="decision-body"><label class="field"><span>${T('审核说明（选填）','Review note (optional)')}</span><textarea data-note="${p.id}" placeholder="${T('写下对这份角色资料的审核说明……','Add a note about this profile…')}">${esc(state.notes[p.id]||'')}</textarea></label></div><div class="decision-actions"><p class="action-help">${T('退回本次资料，不会停用角色。','Returning this profile does not disable the persona.')}</p>${btn(T('退回本次资料','Return profile'),'return-profile')}${btn(T('批准角色资料','Approve profile'),'approve-profile','primary')}</div></section>`;
else content+=`<div class="readback-result"><strong>${p.status==='approved'?T('这份资料已批准','This profile has been approved'):T('这份资料已退回','This profile has been returned')}</strong><p>${T('关联发言仍需在评价与回复审核中分别处理。','Associated posts still need separate moderation.')}</p></div>`;
content+=`<section class="publication-area"><div><h3>${T('角色状态管理','Persona availability')} · ${p.disabled?T('已停用','Disabled'):T('启用中','Enabled')}</h3><p>${T('与资料审核分开；停用角色不会自动隐藏历史发言。','Separate from profile review. Disabling does not hide past posts.')}</p></div>${btn(p.disabled?T('重新启用角色','Re-enable persona'):T('停用角色','Disable persona'),p.disabled?'enable-profile':'disable-profile',p.disabled?'':'danger')}</section>`;return content;}
function accountForm(){return `<section class="panel form-card"><h2>${T('创建普通账号','Create an ordinary account')}</h2><p>${T('为已有参与者创建登录账号。此处不分配网站或世界管理权限。','Create a login account for a participant. No site or world management permissions are assigned here.')}</p>${notice('info',T('创建账号，不是授予权限','Account creation does not grant permissions'),`<p>${T('账号与角色分开。创建后不会自动建立角色，也不会获得管理员身份。','Accounts and personas are separate. Creating an account does not create a persona or administrator access.')}</p>`,'info')}<form id="create-account" novalidate aria-busy="${Boolean(state.accountPending)}"><label class="field"><span>${T('邮箱','Email')}</span><input type="email" name="email" autocomplete="off" value="${esc(state.formEmail)}" placeholder="reader@plotstay.example" required aria-describedby="account-error"><span class="help">${T('使用邮箱登录；不会在这里添加额外的权限选项。','The email is used to sign in.')}</span></label><label class="field"><span>${T('初始密码','Initial password')}</span><div class="password-wrap"><input type="password" id="new-password" name="password" value="${esc(state.formPassword)}" autocomplete="new-password" minlength="12" placeholder="${T('至少 12 位','At least 12 characters')}" required><button type="button" data-action="password-visibility" aria-label="${T('显示或隐藏密码','Show or hide password')}">${icon('eye')}</button></div><span class="help">${T('原型演示：不要输入真实账号密码。','Prototype only: do not enter real credentials.')}</span></label><p id="account-error" class="error-text" role="alert">${esc(state.accountError||'')}</p><div class="form-end"><p>${T('创建类型：普通账号','Account type: ordinary account')}</p><button class="btn primary" type="submit" ${state.accountPending||state.accountUnknown?'disabled':''}>${state.accountPending?T('正在提交…','Submitting…'):T('创建普通账号','Create ordinary account')}</button></div></form>${state.accountUnknown?notice('',T('结果尚待确认','Outcome not confirmed'),`<p>${T('演示：请求超时。暂不能判断是否创建成功，请先核对，避免重复提交。','Demo: the request timed out. Success is unknown. Check the outcome before submitting again.')}</p>${btn(T('核对演示结果','Check demo outcome'),'check-account')}`,'warn'):''}${state.createdEmail?`<div class="readback-result"><strong>${T('演示：账号已创建','Demo: account created')} · ${esc(state.createdEmail)}</strong><p>${T('类型：普通账号。未授予网站或世界管理权限。没有创建真实账号。','Ordinary account. No management access granted. No real account was created.')}</p></div>`:''}</section>`;}
const bindings=[{id:'b1',world:'lathe',name:'第七客舍',en:'Seventh Guesthouse',kind:'stay',owner:'xingwu',provider:'p2',locked:true},{id:'b2',world:'lathe',name:'轨道接驳导览',en:'Orbital Transfer Walk',kind:'experience',owner:'xingwu',provider:'p2',locked:false},{id:'b3',world:'lathe',name:'锈红修理室',en:'Rust-red Repair Room',kind:'service',owner:'mara.notes',provider:'p3',locked:false},{id:'b4',world:'mist',name:'山路驿站',en:'Mountain Road Lodge',kind:'stay',owner:'xingwu',provider:'p2',locked:true}];
function bindingForm(){if(state.scenario==='error')return notice('',T('无法加载绑定信息','Could not load assignments'),`<p>${T('没有取得当前条目状态，请重新加载后再核对。','The current entry status is unavailable. Reload before checking its assignment.')}</p>${btn(T('重新加载','Reload'),'retry')}`,'warn');const b=bindings.find(x=>x.id===state.bindingEntry)||bindings[0];return `<section class="panel binding-card"><div class="panel-title"><h2>${T('条目提供者绑定','Assign an entry provider')}</h2></div><p class="small muted" style="margin-bottom:21px">${T('先选择世界和条目，再核对当前提供者、所有者与可修改状态。','Choose a world and entry, then check its owner, provider and assignment status.')}</p><div class="binding-lookup"><label class="field"><span>${T('所属世界','World')}</span><select data-select="binding-world"><option value="lathe" ${state.bindingWorld==='lathe'?'selected':''}>${worldName('lathe')}</option><option value="mist" ${state.bindingWorld==='mist'?'selected':''}>${worldName('mist')}</option></select></label><label class="field"><span>${T('条目','Entry')}</span><select data-select="binding-entry">${bindings.filter(x=>x.world===state.bindingWorld).map(x=>`<option value="${x.id}" ${x.id===b.id?'selected':''}>${kindName(x.kind)} · ${esc(T(x.name,x.en))}</option>`).join('')}</select></label></div><section class="binding-summary"><div class="summary-head"><h2>${esc(T(b.name,b.en))}</h2>${tag(b.locked?T('已永久锁定','Permanently locked'):b.owner==='xingwu'?T('可修改','Editable'):T('只读','Read only'),b.locked?'waiting':'subtle')}</div><dl class="binding-facts"><div><dt>${T('所属世界','World')}</dt><dd>${worldName(b.world)}</dd></div><div><dt>${T('条目类型','Type')}</dt><dd>${kindName(b.kind)}</dd></div><div><dt>${T('条目所有者','Entry owner')}</dt><dd>${esc(b.owner)} ${b.owner==='xingwu'?T('（当前账号）','(you)'):''}</dd></div><div><dt>${T('当前提供者角色','Current provider')}</dt><dd>${esc(profileName(b.provider))}</dd></div></dl></section>${b.locked?notice('',T('经营角色已永久锁定','The provider assignment is permanently locked'),`<p>${T('此条目已首次成功送审或发布，不能更换经营角色。撤回、下架或网站管理员身份都不会解除锁定。','This entry has been successfully submitted or published. Its provider cannot be replaced. Withdrawal, unpublishing or site administrator status does not remove the lock.')}</p>`,'lock'):b.owner!=='xingwu'?notice('',T('你不是该条目的所有者','You do not own this entry'),`<p>${T('网站管理员身份不绕过条目所有权限制。此处只展示当前绑定信息，不提供修改操作。','Site administrator status does not override ownership. The assignment is shown read-only.')}</p>`,'lock'):state.scenario==='no-candidates'?notice('info',T('没有可选角色','No eligible personas'),`<p>${T('当前账号没有可绑定的已保存、启用中角色。可先在“我的角色”准备角色，再返回核对。','This account has no saved, enabled personas available to assign. Prepare a persona in My personas, then return to check.')}</p>`,'info'):`<div class="binding-provider"><label class="field"><span>${T('更换为：我的提供者角色','Assign one of my provider personas')}</span><select data-select="binding-persona" ${state.bindingPending||state.bindingUnknown?'disabled':''}><option value="p2" ${state.bindingPersona==='p2'?'selected':''}>${T('塞缪尔 · xingwu','Samuel · xingwu')}</option><option value="p9" ${state.bindingPersona==='p9'?'selected':''}>${T('索恩 · xingwu','Thorne · xingwu')}</option></select></label><div class="binding-change"><span class="muted">${T('本次变更','Change')}</span><strong>${esc(profileName(b.provider))}</strong>${icon('arrow')}<strong>${state.bindingPersona==='p9'?T('索恩','Thorne'):T('塞缪尔','Samuel')}</strong></div>${notice('',T('首次成功送审或发布后将永久锁定','Locks permanently at first successful submission or publication'),`<p>${T('这次绑定不会转移条目所有权，也不会改写旧凭条或历史回复的署名。','This does not transfer entry ownership or rewrite historical receipt and reply signatures.')}</p>`,'warn')}${btn(state.bindingPending?T('正在保存…','Saving…'):T('保存绑定','Save assignment'),'save-binding','primary',state.bindingPersona===b.provider||state.bindingPending||state.bindingUnknown?'disabled':'')}</div>`}${state.bindingError?`<p class="error-text" role="alert">${esc(state.bindingError)}</p>`:''}${state.bindingUnknown?notice('',T('保存结果尚待确认','Assignment outcome not confirmed'),`<p>${T('演示：请求超时。先重新核对当前绑定，避免重复保存。','Demo: request timed out. Check the current assignment before saving again.')}</p>${btn(T('核对演示结果','Check demo outcome'),'check-binding')}`,'warn'):''}${state.bindingSaved?`<div class="readback-result"><strong>${T('演示：绑定已保存','Demo: assignment saved')}</strong><p>${T('只修改了本地示例，没有更改真实条目。','Only the local example changed. No live entry was modified.')}</p></div>`:''}<p class="footnote">${T('这里不提供强制更换或解除锁定功能。','Force replacement and unlocking are not available here.')}</p></section>`;}
function previewControls(){return `<div class="preview-bar"><span class="preview-mark">${T('UI 设计预览 · 示例数据','UI DESIGN PREVIEW · FICTIONAL DATA')}</span><span class="preview-copy">${T('不连接真实接口，不会发布内容或创建账号。','No live APIs. No real publications or accounts.')}</span><button data-action="preview-options">${T('预览选项','Preview options')} ${state.options?'▾':'▴'}</button></div>${state.options?`<section class="preview-options" aria-label="${T('原型预览设置','Prototype settings')}"><h2>${T('原型预览设置','Prototype settings')}</h2><p class="small muted">${T('这些控件仅用于检查设计，不属于正式后台。','These controls test the design; they are not part of the product.')}</p><label class="field"><span>${T('预览身份','Preview identity')}</span><select data-select="role"><option value="site" ${state.role==='site'?'selected':''}>${T('网站管理员','Site administrator')}</option><option value="world" ${state.role==='world'?'selected':''}>${T('世界管理员','World administrator')}</option></select></label><label class="field"><span>${T('模拟状态','Simulated state')}</span><select data-select="scenario">${[['normal',T('正常','Normal')],['empty',T('空列表','Empty queue')],['error',T('加载失败','Loading error')],['conflict',T('详情：已被他人处理','Detail: handled by someone else')],['no-candidates',T('绑定：无候选角色','Assignment: no eligible personas')],['save-error',T('表单：保存失败','Form: save failed')],['unknown',T('表单：结果待确认','Form: outcome unknown')]].map(([v,n])=>`<option value="${v}" ${state.scenario===v?'selected':''}>${n}</option>`).join('')}</select></label><div class="preview-links">${btn(T('评价列表','Review queue'),'scene-reviews','small')}${btn(T('联合批准','Combined approval'),'scene-combined','small')}${btn(T('回复详情','Reply detail'),'scene-reply','small')}${btn(T('资料列表','Profile queue'),'scene-profiles','small')}${btn(T('创建账号','Create account'),'scene-accounts','small')}${btn(T('绑定状态','Assignment states'),'scene-bindings','small')}</div>${btn(T('重置全部示例','Reset all examples'),'reset-demo','small')}</section>`:''}`;}
let toastTimer;
function toast(text){document.getElementById('toast-root').innerHTML=`<div class="toast">${esc(text)}</div>`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>document.getElementById('toast-root').replaceChildren(),3800);}
function render(){const rt=route();if(rt.view!=='site'||rt.tab!=='accounts')state.formPassword='';document.documentElement.lang=state.lang==='en'?'en':'zh-CN';document.title=T('Plotstay · 审核工作台 UI 预览','Plotstay · Moderation UI preview');let content;if(rt.view==='site'&&rt.detail)content=profileDetail();else if(rt.view==='site')content=sitePage();else content=rt.detail?recordDetail():moderationList();document.getElementById('new-workspace').innerHTML=shell(content);document.getElementById('preview-ui').innerHTML=previewControls();requestAnimationFrame(()=>{const tab=document.querySelector('.tabs button.active');if(tab){const parent=tab.parentElement,a=tab.getBoundingClientRect(),b=parent.getBoundingClientRect();if(a.right>b.right)parent.scrollLeft+=a.right-b.right;else if(a.left<b.left)parent.scrollLeft-=b.left-a.left;}if(state.restoreY!==null){window.scrollTo(0,state.restoreY);state.restoreY=null}else if(state.preserveY!==null){window.scrollTo(0,state.preserveY);state.preserveY=null}});}
function closeModal(){state.modal=null;document.getElementById('modal-root').replaceChildren();document.body.style.overflow='';state.focusBefore?.focus?.();}
function showModal(type,callback){const r=currentRecord(),p=route().view==='site'?pBy(route().detail):r?pBy(r.profile):null;state.focusBefore=document.activeElement;let title='',body='',button='',danger=false;
if(type==='publish'){title=T('批准角色资料并发布此发言？','Approve the profile and publish this post?');body=`<p>${T('将执行以下两项决定：','The following two decisions will be applied:')}</p><div class="effect-row"><strong>${T('批准角色资料','Approve profile')} · ${esc(personName(p))} v${p.version}</strong><p>${T('网站级决定；不局限于当前列表所选世界。','Site-wide decision, not limited to the current world filter.')}</p></div><div class="effect-row"><strong>${r.type==='reply'?T('发布此回复','Publish this reply'):T('发布此评价','Publish this review')} · v${r.version}</strong><p>${worldName(r.world)} / ${esc(T(r.entry,r.entryEn))}<br>${r.published?T('替换当前公开版本。','Replaces the current public version.'):T('本次送审内容将对外展示。','Makes the submitted content public.')}</p></div><p style="margin-top:16px"><strong>${T('不会自动发布其他发言或后续草稿。','Other posts and later drafts will not be published.')}</strong></p>`;button=T('确认两项操作','Confirm both actions');}
if(type==='hide'){title=T('隐藏这条公开内容？','Hide this publication?');body=`<p><strong>${esc(T(r.title,r.titleEn))}</strong></p><p>${T('隐藏后不再对外展示。内容及历史仍保留，这不是删除操作。','The content will no longer be public. Its content and history are kept; this is not deletion.')}</p><p>${T('如有新版本正在审核，其审核状态保持不变。','Any pending submission remains pending.')}</p>`;button=T('确认隐藏','Hide publication');danger=true;}
if(type==='restore'){title=T('恢复历史公开版本？','Restore a past publication?');body=`<div class="effect-row"><strong>${T('历史公开版','Past publication')} · v${r.pastPublication?.version||r.pubVersion}</strong><p>2026-10-12 16:40 · ${esc(profileName(r.profile))}</p></div><p>${esc(C(r.pastPublication?.body[0]||r.publicBody[0],r.pastPublication?.bodyEn[0]||r.publicBodyEn[0]))}</p><p><strong>${T('将恢复此版本的公开内容和署名，不会发布后续草稿。','Restores this version’s public content and signature, not a later draft.')}</strong></p><p>${T('当前待审版本保持独立，不会因此被批准。','The pending submission remains separate and is not approved by this action.')}</p>`;button=T('恢复此公开版本','Restore this publication');}
if(type==='disable'){title=T(`停用「${personName(p)}」？`,`Disable ${personName(p)}?`);body=`<p>${T('这会停用该角色，但不是账号封禁，也不是退回某一份资料。','This disables the persona; it does not ban the account or return a profile submission.')}</p><p><strong>${T('已经公开的评价与回复不会自动隐藏。','Published reviews and replies will not be hidden automatically.')}</strong></p><p>${T('需要撤下某条发言时，请到评价与回复审核中单独处理。','Moderate individual posts separately to remove them from public view.')}</p>`;button=T('停用角色','Disable persona');danger=true;}
if(type==='leave'){title=T('离开当前审核详情？','Leave this review?');body=`<p>${T('审核说明尚未提交。离开不会执行任何审核决定；本次预览会暂存这段说明，返回时仍可继续。','Your note has not been submitted. Leaving makes no decision. This preview keeps the note in memory so you can return to it.')}</p>`;button=T('离开并暂存说明','Leave and keep note');}
if(type==='binding'){const b=bindings.find(x=>x.id===state.bindingEntry);title=T('保存这次提供者绑定？','Save this provider assignment?');body=`<div class="effect-row"><strong>${esc(T(b.name,b.en))}</strong><p>${esc(profileName(b.provider))} → ${esc(profileName(state.bindingPersona))}</p></div><p>${T('不会转移条目所有权，不会改写历史凭条和回复署名。','Does not transfer entry ownership or rewrite past receipts and signatures.')}</p><p>${T('首次成功送审或发布后，经营角色将永久锁定。','The provider will lock permanently after the first successful submission or publication.')}</p>`;button=T('保存绑定','Save assignment');}
state.modal={type,callback};document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${title}</h2><span class="modal-icon">${icon(danger?'warn':'shield')}</span></div><div class="modal-body">${body}</div><div class="modal-footer">${btn(T('取消','Cancel'),'cancel-modal')}${btn(button,'confirm-modal',danger?'danger solid':'primary')}</div></section></div>`;document.body.style.overflow='hidden';setTimeout(()=>document.querySelector('[data-action="cancel-modal"]')?.focus(),10);}
function publishRecord(){const r=currentRecord(),p=pBy(r.profile),joint=p.status==='pending';if(joint){p.status='approved';p.currentVersion=p.version;p.oldBio=p.bio;p.oldBioEn=p.bioEn;}r.submission='none';r.published=true;r.hidden=false;r.hasHistory=true;r.pubVersion=r.version;r.publicBody=r.body.slice();r.publicBodyEn=r.bodyEn.slice();r.publicBio=p.bio;r.publicBioEn=p.bioEn;r.publicProfileVersion=p.version;state.notes[r.id]='';state.success[r.id]=joint?T(`角色资料 v${p.version} 已批准；当前${r.type==='reply'?'回复':'评价'} v${r.version} 已发布。其他发言未自动发布。`,`Profile v${p.version} approved; this ${r.type} v${r.version} published. Other posts were not published.`):T(`本次送审 v${r.version} 已发布。`,`Submission v${r.version} published.`);state.preserveY=window.scrollY;render();}
function backModeration(){const r=route(),item=recordBy(r.detail);go({view:'moderation',tab:item?.type==='reply'?'replies':r.tab==='replies'?'replies':'reviews',detail:'',version:'submitted'},{restore:true});}
function resetAll(){cancelDemoBinding();cancelDemoAccount();state.accountError='';state.accountUnknown=false;initData();bindings.forEach(b=>{if(b.id==='b2')b.provider='p2'});state.notes={};state.success={};state.scenario='normal';state.createdEmail='';state.formEmail='';state.formPassword='';state.tabMemory={};state.bindingSaved=false;state.bindingEntry='b1';state.bindingWorld='lathe';state.bindingPersona='p2';state.fromRecord=null;state.options=false;state.role='site';go({view:'moderation',tab:'reviews',detail:'',q:'',scope:'all',status:'pending',page:1,enabled:'all'},{skipGuard:true});render();}
document.addEventListener('click',e=>{const target=e.target.closest('[data-action],[data-nav]');if(!target)return;if(target.tagName==='A')e.preventDefault();const nav=target.dataset.nav;if(nav){const [view,tab]=nav.split(':');if(!['site','moderation'].includes(view)){toast(T('本稿只设计两个审核页面，这个入口沿用原系统，未模拟。','This preview covers the two moderation pages only. This existing section is not simulated.'));return;}state.menu=false;go({view,tab,detail:'',page:1,status:'pending',q:''});return;}
const a=target.dataset.action,id=target.dataset.id,value=target.dataset.value;
if(a==='skip-content'){document.getElementById('main').focus();return;}
if(a==='outside'){toast(T('本稿仅包含两个审核页面；未跳转到真实系统。','Only the two moderation pages are included. No live system was opened.'));return;}
if(a==='ui-zh'||a==='ui-en'){state.lang=a==='ui-en'?'en':'zh';const u=new URL(location.href);u.searchParams.set('lang',state.lang);history.replaceState(null,'',u);state.preserveY=window.scrollY;render();return;}
if(a==='content-zh'||a==='content-en'){state.contentLang=a==='content-en'?'en':'zh';state.preserveY=window.scrollY;render();return;}
if(a==='menu'){state.menu=!state.menu;render();return;}
if(a==='preview-options'){state.options=!state.options;document.getElementById('preview-ui').innerHTML=previewControls();return;}
if(a==='mod-tab'){const rt=route();state.tabMemory[rt.tab]={page:rt.page,q:rt.q,status:rt.status};go({tab:value,detail:'',...(state.tabMemory[value]||{page:1,q:'',status:'pending'})});return;}
if(a==='site-tab'){go({tab:value,detail:'',page:1,q:'',status:'pending',enabled:'all'});return;}
if(a==='page'){go({page:Number(value)});return;}
if(a==='reset-filters'){if(state.scenario==='empty')state.scenario='normal';go({q:'',status:'pending',page:1,enabled:'all'});render();return;}
if(a==='retry'){state.scenario='normal';render();return;}
if(a==='resolve-conflict'){const r=currentRecord();r.submission='none';r.published=true;r.hasHistory=true;state.scenario='normal';state.success[r.id]=T('最新状态：此版本已由另一位管理员发布。','Latest status: another administrator published this version.');render();return;}
if(a==='open-record'){const r=recordBy(id);state.fromRecord=null;go({view:'moderation',tab:r.type==='reply'?'replies':'reviews',detail:id,version:r.submission==='pending'?'submitted':r.hasHistory?'public':'submitted'},{remember:true});return;}
if(a==='open-profile'){if(state.role!=='site')return;if(route().view==='moderation'&&route().detail)state.fromRecord={...route()};go({view:'site',tab:'profiles',detail:id},{remember:true});return;}
if(a==='back-moderation'){backModeration();return;}
if(a==='back-profiles'){go({view:'site',tab:'profiles',detail:'',version:'submitted'},{restore:true});return;}
if(a==='back-source'){if(state.fromRecord)go(state.fromRecord);return;}
if(a==='version'){go({version:value},{preserve:true});return;}
if(a==='publish-record'){const r=currentRecord(),p=pBy(r.profile);if(p.status==='pending')showModal('publish',publishRecord);else publishRecord();return;}
if(a==='return-record'){const r=currentRecord();r.submission='rejected';state.success[r.id]=T('本次送审已退回。原有公开内容保持不变。','Submission returned. Any existing publication is unchanged.');state.notes[r.id]='';state.preserveY=window.scrollY;render();return;}
if(a==='hide-record'){showModal('hide',()=>{const r=currentRecord();r.published=false;r.hidden=true;state.success[r.id]=T('公开内容已隐藏。待审版本及历史记录保留。','Publication hidden. The pending version and history are preserved.');render()});return;}
if(a==='restore-record'){showModal('restore',()=>{const r=currentRecord();r.published=true;r.hidden=false;if(r.pastPublication){r.pubVersion=r.pastPublication.version;r.publicBody=r.pastPublication.body.slice();r.publicBodyEn=r.pastPublication.bodyEn.slice();r.publicProfileVersion=r.pastPublication.profileVersion;r.publicBio=r.pastPublication.bio;r.publicBioEn=r.pastPublication.bioEn;}state.success[r.id]=T('历史公开版已恢复；待审版本没有被批准。','Past publication restored; the pending submission was not approved.');render()});return;}
if(a==='approve-profile'||a==='return-profile'){const p=pBy(route().detail);p.status=a==='approve-profile'?'approved':'rejected';if(p.status==='approved'){p.currentVersion=p.version;p.oldBio=p.bio;p.oldBioEn=p.bioEn;}state.notes[p.id]='';state.success[p.id]=p.status==='approved'?T('角色资料已批准。关联评价与回复没有自动发布。','Profile approved. Associated reviews and replies were not published.'):T('本次资料已退回。角色启用状态保持不变。','Profile returned. Persona availability is unchanged.');state.preserveY=window.scrollY;render();return;}
if(a==='disable-profile'){showModal('disable',()=>{const p=pBy(route().detail);p.disabled=true;state.success[p.id]=T('角色已停用；历史公开发言没有自动隐藏。','Persona disabled. Past public posts were not hidden.');render()});return;}
if(a==='enable-profile'){pBy(route().detail).disabled=false;state.success[route().detail]=T('角色已重新启用；没有自动批准资料或发布发言。','Persona re-enabled. No profiles or posts were approved automatically.');render();return;}
if(a==='check-account'){state.accountUnknown=false;state.createdEmail=state.accountAttemptEmail;state.formPassword='';state.accountError='';render();return;}
if(a==='password-visibility'){const el=document.getElementById('new-password');el.type=el.type==='password'?'text':'password';return;}
if(a==='save-binding'){showModal('binding',submitDemoBinding);return;}
if(a==='check-binding'){const attempt=state.bindingAttempt;bindings.find(x=>x.id===attempt.entry).provider=attempt.persona;state.bindingUnknown=false;state.bindingSaved=true;render();return;}
if(a==='cancel-modal'){closeModal();return;}
if(a==='confirm-modal'){const cb=state.modal?.callback;closeModal();cb?.();return;}
if(a==='reset-demo'){resetAll();return;}
if(a.startsWith('scene-')){state.options=false;state.scenario='normal';const scene=a.replace('scene-','');if(['profiles','accounts','bindings','combined'].includes(scene))state.role='site';const routes={reviews:{view:'moderation',tab:'reviews'},combined:{view:'moderation',tab:'reviews',detail:'r1'},reply:{view:'moderation',tab:'replies',detail:'a1'},profiles:{view:'site',tab:'profiles'},accounts:{view:'site',tab:'accounts'},bindings:{view:'site',tab:'bindings'}};go({detail:'',version:'submitted',q:'',status:'pending',page:1,...routes[scene]},{skipGuard:true});render();}
});
document.addEventListener('change',e=>{const s=e.target.dataset.select;if(!s)return;const v=e.target.value;if(['scope','status','enabled'].includes(s)){go({[s]:v,page:1});return;}if(s==='role'){state.role=v;state.options=false;if(v==='world'&&route().view==='site')go({view:'moderation',tab:'reviews',detail:''},{skipGuard:true});render();return;}if(s==='scenario'){state.scenario=v;state.options=false;if(v==='conflict'&&!route().detail)go({view:'moderation',tab:'reviews',detail:'r1',version:'submitted'},{skipGuard:true});render();return;}if(s==='binding-world'){cancelDemoBinding();state.bindingWorld=v;state.bindingEntry=bindings.find(b=>b.world===v).id;state.bindingSaved=false;render();return;}if(s==='binding-entry'){cancelDemoBinding();state.bindingEntry=v;state.bindingSaved=false;state.bindingPersona='p2';render();return;}if(s==='binding-persona'){if(state.bindingPending||state.bindingUnknown){render();return;}state.bindingError='';state.bindingPersona=v;state.bindingSaved=false;render();}});
document.addEventListener('input',e=>{if(e.target.dataset.note)state.notes[e.target.dataset.note]=e.target.value;if(e.target.closest('#create-account')){if(e.target.name==='email')state.formEmail=e.target.value;if(e.target.name==='password')state.formPassword=e.target.value;}});
document.addEventListener('submit',e=>{if(e.target.id==='queue-search'){e.preventDefault();go({q:new FormData(e.target).get('q')||'',page:1});return;}if(e.target.id==='create-account'){e.preventDefault();if(state.accountPending)return;const f=e.target;const email=f.elements.email.value.trim(),password=f.elements.password.value;const err=document.getElementById('account-error');if(!email||!f.elements.email.validity.valid){err.textContent=T('请填写有效的邮箱地址。','Enter a valid email address.');f.elements.email.focus();return;}if(password.length<12){err.textContent=T('初始密码至少需要 12 位。','The initial password must be at least 12 characters.');f.elements.password.focus();return;}submitDemoAccount(f,email);}});
document.addEventListener('keydown',e=>{if(!state.modal)return;if(e.key==='Escape'){e.preventDefault();closeModal();return;}if(e.key==='Tab'){const elems=Array.from(document.querySelectorAll('.modal button:not(:disabled),.modal input,.modal a[href]'));const first=elems[0],last=elems[elems.length-1];if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault()}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault()}}});
window.addEventListener('hashchange',()=>{if(route().view!=='site'||route().tab!=='bindings')cancelDemoBinding();if(route().view!=='site'||route().tab!=='accounts'){cancelDemoAccount();state.formPassword='';}if(state.preserveY===null&&state.restoreY===null)window.scrollTo(0,0);render();});
window.addEventListener('beforeunload',e=>{if(Object.values(state.notes).some(x=>x?.trim())){e.preventDefault();e.returnValue='';}});

let bindingTimer;
function cancelDemoBinding(){clearTimeout(bindingTimer);state.bindingPending=false;state.bindingUnknown=false;state.bindingError='';state.bindingSaved=false;}
function submitDemoBinding(){
 const attempt={entry:state.bindingEntry,persona:state.bindingPersona};
 const scenario=state.scenario;state.bindingAttempt=attempt;state.bindingPending=true;state.bindingError='';render();
 bindingTimer=setTimeout(()=>{
  state.bindingPending=false;
  if(scenario==='save-error')state.bindingError=T('演示：保存失败，原绑定保持不变。','Demo: save failed. The original assignment remains.');
  else if(scenario==='unknown')state.bindingUnknown=true;
  else {bindings.find(x=>x.id===attempt.entry).provider=attempt.persona;state.bindingSaved=true;}
  render();
 },700);
}
let accountTimer;
function cancelDemoAccount(){clearTimeout(accountTimer);state.accountPending=false;}
function submitDemoAccount(form,email){
 state.createdEmail='';state.accountError='';state.accountPending=true;
 state.accountAttemptEmail=email;state.formPassword='';form.elements.password.value='';
 const scenario=state.scenario;render();
 accountTimer=setTimeout(()=>{
  state.accountPending=false;
  if(scenario==='save-error')state.accountError=T('演示：创建失败，请检查邮箱或稍后重试。未创建真实账号。','Demo: creation failed. Check the email or try later. No real account was created.');
  else if(scenario==='unknown')state.accountUnknown=true;
  else state.createdEmail=email;
  render();
 },900);
}
function initPreviewURL(){
 const p=new URLSearchParams(location.search);
 state.lang=p.get('lang')==='en'?'en':'zh';state.contentLang=state.lang;
 state.role=p.get('actor')==='world'?'world':'site';
 if(['normal','empty','error','conflict','no-candidates','save-error','unknown'].includes(p.get('scenario')))state.scenario=p.get('scenario');
 const b=bindings.find(x=>x.id===p.get('entry'));if(b){state.bindingWorld=b.world;state.bindingEntry=b.id;state.bindingPersona=b.provider;}
 if(!location.hash){
  const r=new URLSearchParams();for(const key of ['view','tab','detail','scope','status','q','page','version','enabled'])if(p.has(key))r.set(key,p.get(key));
  history.replaceState(null,'',location.pathname+location.search+(r.size?'#'+r.toString():''));
 }
}
initPreviewURL();

render();
// Explicitly exposed for local screenshot verification, not for production integration.
window.PlotstayPreview={state,route,render,resetAll,getData:()=>({profiles,reviews,replies})};


